Q: Unable to transform split string A: <p>If you prefer to work with line in string, then another solution to your problem is to use <code>std::generator</code>. This mixes well with <code>std::from_chars</code>.</p>
<pre class="lang-cpp prettyprint-override"><code>import std;

template &lt;std::integral Int&gt;
auto parse_ints_from(std::string_view in, int base = 10)
    -&gt; std::generator&lt;Int&gt; {
    auto b = in.data();
    auto e = b + in.size();
    while (b != e) {
        while (b != e &amp;&amp; std::isspace(*b)) {
            ++b;
        }
        if (b == e) {
            break;
        }

        Int result = 0;
        auto [ptr, ec] = std::from_chars(b, e, result, base);
        if (ec != std::errc{}) {
            throw std::system_error{std::make_error_code(ec)};
        }
        co_yield result;
        b = ptr;
    }
}

int main() {
    std::string line;
    while (getline(std::cin, line)) {
        try {
            auto v =
                parse_ints_from&lt;int&gt;(line) | std::ranges::to&lt;std::vector&gt;();
            std::println(&quot;v = {}&quot;, v);

        } catch (const std::exception&amp; e) {
            std::println(&quot;Exception: {}&quot;, e.what());
        }
    }
}
</code></pre>
